/*
 * Tests for the SZ-Link security layer (szlink_sec.h), FEC envelopes and their
 * integration in szlink_frame.h. Replays vectors generated by the Python
 * implementation (szlink_test_vectors.h) to prove byte-for-byte interop.
 * Built and run by scripts/test_szlink.sh.
 */
#define SZLINK_SEC_IMPLEMENTATION
#define SZLINK_ECC_IMPLEMENTATION
#include "spacezet/szlink.h"
#include "szlink_frame.h"
#include "szlink_test_vectors.h"

#include <stdio.h>
#include <string.h>

static int failures = 0;
#define CHECK(cond)                                                            \
    do {                                                                       \
        if (!(cond)) {                                                         \
            fprintf(stderr, "%s:%d: CHECK failed: %s\n", __FILE__, __LINE__,   \
                    #cond);                                                    \
            failures++;                                                        \
        }                                                                      \
    } while (0)

static szlink_sec_t gcs, veh;

/* Paired ground station and vehicle with the vector keys, session confirmed. */
static void pair(uint32_t now)
{
    uint8_t pub[32], kex_init[SZLINK_SEC_KEX_INIT_LEN], kex_resp[SZLINK_SEC_KEX_RESP_LEN];
    uint8_t hdr[9] = {0xFD, 2, 1, 0, 1, 1, 0, 0, 0}, pl[2] = {1, 2}, sec, tag[16];
    static uint64_t ts = 1000;
    szlink_sec_public_key(pub, tv_veh_priv);
    szlink_sec_init(&gcs, SZLINK_SEC_INITIATOR, tv_gcs_priv, pub);
    szlink_sec_public_key(pub, tv_gcs_priv);
    szlink_sec_init(&veh, SZLINK_SEC_RESPONDER, tv_veh_priv, pub);
    CHECK(szlink_sec_kex_init(&gcs, tv_gcs_eph, ts++, now, kex_init) == 0);
    CHECK(szlink_sec_handle_kex_init(&veh, kex_init, tv_veh_eph, now, kex_resp) == 0);
    CHECK(szlink_sec_handle_kex_resp(&gcs, kex_resp, now) == 0);
    CHECK(szlink_sec_seal(&gcs, hdr, pl, 2, SZLINK_SEC_ENCRYPTED, 0, now, &sec, tag) == 16);
    CHECK(szlink_sec_open(&veh, hdr, pl, 2, sec, tag, 16, now) == 0);
    CHECK(veh.cur.valid && !veh.pending.valid);
}

/* seal + open one telemetry frame from a to b; returns open() result */
static int send(szlink_sec_t *a, szlink_sec_t *b, uint32_t t_tx, uint32_t t_rx, uint8_t mode)
{
    uint8_t hdr[9] = {0xFD, 4, 1, 0, 1, 1, 0, 0, 0}, pl[4] = {9, 8, 7, 6}, sec, tag[16];
    int r;
    if (szlink_sec_seal(a, hdr, pl, 4, mode, 0, t_tx, &sec, tag) != 16) {
        return -100;
    }
    r = szlink_sec_open(b, hdr, pl, 4, sec, tag, 16, t_rx);
    if (r == 0 && !(pl[0] == 9 && pl[3] == 6)) {
        return -101;
    }
    return r;
}

static void test_rfc8439_aead(void)
{
    uint8_t key[32], nonce[12] = {7, 0, 0, 0, 0x40, 0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47};
    const uint8_t ad[12] = {0x50, 0x51, 0x52, 0x53, 0xc0, 0xc1, 0xc2, 0xc3, 0xc4, 0xc5, 0xc6, 0xc7};
    const char *pt = "Ladies and Gentlemen of the class of '99: If I could offer you only one tip "
                     "for the future, sunscreen would be it.";
    const uint8_t expect[16] = {0x1a, 0xe1, 0x0b, 0x59, 0x4f, 0x09, 0xe2, 0x6a,
                                0x7e, 0x90, 0x2e, 0xcb, 0xd0, 0x60, 0x06, 0x91};
    uint8_t ct[128], tag[16];
    size_t i, n = strlen(pt);
    for (i = 0; i < 32; i++) {
        key[i] = (uint8_t)(0x80 + i);
    }
    crypto_ietf_chacha20_ctr(ct, (const uint8_t *)pt, n, key, nonce, 1);
    CHECK(ct[0] == 0xd3 && ct[1] == 0x1a);
    szlink_sec_tag_(tag, key, nonce, ad, 4, ad + 4, 8, NULL, 0, ct, n);
    CHECK(memcmp(tag, expect, 16) == 0);
}

static void test_vectors_handshake(void)
{
    uint8_t pub[32], out_init[SZLINK_SEC_KEX_INIT_LEN], out_resp[SZLINK_SEC_KEX_RESP_LEN];
    szlink_sec_public_key(pub, tv_veh_priv);
    szlink_sec_init(&gcs, SZLINK_SEC_INITIATOR, tv_gcs_priv, pub);
    szlink_sec_public_key(pub, tv_gcs_priv);
    szlink_sec_init(&veh, SZLINK_SEC_RESPONDER, tv_veh_priv, pub);
    CHECK(szlink_sec_needs_kex(&gcs, 0));
    CHECK(szlink_sec_kex_init(&gcs, tv_gcs_eph, TV_TIMESTAMP_US, 0, out_init) == 0);
    CHECK(memcmp(out_init, tv_kex_init, sizeof(tv_kex_init)) == 0);
    CHECK(!szlink_sec_needs_kex(&gcs, 999));
    CHECK(szlink_sec_handle_kex_init(&veh, tv_kex_init, tv_veh_eph, 0, out_resp) == 0);
    CHECK(memcmp(out_resp, tv_kex_resp, sizeof(tv_kex_resp)) == 0);
    CHECK(szlink_sec_handle_kex_resp(&gcs, tv_kex_resp, 0) == 0);
    CHECK(gcs.cur.valid && veh.pending.valid && !veh.cur.valid);
}

static void test_keys_from_secret(void)
{
    uint8_t v[32], g[32], pub[32];
    szlink_sec_keys_from_secret(tv_secret, v, g);
    szlink_sec_public_key(pub, v);
    CHECK(memcmp(pub, tv_secret_vehicle_pub, 32) == 0);
    szlink_sec_public_key(pub, g);
    CHECK(memcmp(pub, tv_secret_ground_pub, 32) == 0);
}

static void test_vectors_frames(void)
{
    size_t i;
    szlink_frame_parser_t p_veh, p_gcs;
    szlink_frame_parser_init(&p_veh);
    szlink_frame_parser_init(&p_gcs);
    p_veh.sec = &veh;
    p_gcs.sec = &gcs;
    p_veh.fec_nsym = p_gcs.fec_nsym = TV_FEC_NSYM;
    for (i = 0; i < sizeof(tv_frames) / sizeof(tv_frames[0]); i++) {
        const tv_frame_t *f = &tv_frames[i];
        szlink_sec_t *tx = f->gcs_to_vehicle ? &gcs : &veh;
        szlink_frame_parser_t *rx = f->gcs_to_vehicle ? &p_veh : &p_gcs;
        szlink_message_t msg, out;
        uint8_t frame[SZLINK_FRAME_MAX_LEN], env[SZLINK_FRAME_FEC_MAX_LEN], lcid, sec;
        uint8_t flags = f->lcid == SZ_LCID_VIDEO ? SZLINK_SEC_FEC : 0;
        uint16_t n, k;
        int got = 0;
        memset(&msg, 0, sizeof(msg));
        msg.msgid = f->msgid;
        msg.len = f->payload_len;
        msg.sysid = f->sysid;
        msg.compid = f->compid;
        memcpy(_MAV_PAYLOAD_NON_CONST(&msg), f->payload, f->payload_len);
        n = szlink_frame_serialize_secure(frame, &msg, f->lcid, f->mode, flags, tx, f->time_ms);
        CHECK(n != 0);
        if (flags) {
            n = szlink_frame_fec_encode(env, frame, n, TV_FEC_NSYM);
            CHECK(n == f->wire_len && memcmp(env, f->wire, n) == 0);
        } else {
            CHECK(n == f->wire_len && memcmp(frame, f->wire, n) == 0);
        }
        /* the C parser accepts the Python frame */
        rx->now_ms = f->time_ms;
        for (k = 0; k < f->wire_len; k++) {
            got += szlink_frame_parse_char(rx, f->wire[k], &out, &lcid, &sec);
        }
        CHECK(got == 1);
        CHECK(rx->authenticated && lcid == f->lcid && out.msgid == f->msgid);
        CHECK(out.len == f->payload_len &&
              memcmp(_MAV_PAYLOAD(&out), f->payload, f->payload_len) == 0);
        CHECK(rx->via_fec == (flags != 0));
    }
    CHECK(veh.cur.valid && !veh.pending.valid); /* first GCS frame confirmed the keys */
}

static void test_tamper_replay_and_strangers(void)
{
    uint8_t hdr[9] = {0xFD, 4, 1, 0, 1, 1, 0, 0, 0}, pl[4] = {1, 2, 3, 4}, sec, tag[16];
    uint8_t copy_hdr[9], copy_pl[4], i;
    szlink_sec_t stranger;
    uint8_t pub[32], kex_init[SZLINK_SEC_KEX_INIT_LEN], resp[SZLINK_SEC_KEX_RESP_LEN];
    uint8_t other[32];

    pair(0);
    CHECK(szlink_sec_seal(&gcs, hdr, pl, 4, SZLINK_SEC_ENCRYPTED, 0, 5, &sec, tag) == 16);
    for (i = 1; i < 9; i++) {
        if (i == 3) {
            continue; /* SEQ only selects the counter */
        }
        memcpy(copy_hdr, hdr, 9);
        memcpy(copy_pl, pl, 4);
        copy_hdr[i] ^= 1;
        CHECK(szlink_sec_open(&veh, copy_hdr, copy_pl, 4, sec, tag, 16, 5) != 0);
        CHECK(memcmp(copy_pl, pl, 4) == 0); /* untouched on failure */
    }
    memcpy(copy_pl, pl, 4);
    CHECK(szlink_sec_open(&veh, hdr, copy_pl, 4, sec ^ SZLINK_SEC_FEC, tag, 16, 5) != 0);
    CHECK(szlink_sec_open(&veh, hdr, copy_pl, 4, sec, tag, 16, 5) == 0);
    CHECK(copy_pl[0] == 1 && copy_pl[3] == 4);
    memcpy(copy_pl, pl, 4);
    CHECK(szlink_sec_open(&veh, hdr, copy_pl, 4, sec, tag, 16, 5) != 0); /* replay */

    /* a ground station with another key cannot start a session */
    for (i = 0; i < 32; i++) {
        other[i] = (uint8_t)(i + 50);
    }
    szlink_sec_public_key(pub, tv_veh_priv);
    szlink_sec_init(&stranger, SZLINK_SEC_INITIATOR, other, pub);
    CHECK(szlink_sec_kex_init(&stranger, tv_gcs_eph, 5000, 0, kex_init) == 0);
    CHECK(szlink_sec_handle_kex_init(&veh, kex_init, tv_veh_eph, 1, resp) == SZLINK_SEC_ERR_AUTH);
    CHECK(!veh.pending.valid);
    CHECK(send(&gcs, &veh, 10, 10, SZLINK_SEC_SIGNED) == 0);
}

static void test_counter_loss_and_reorder(void)
{
    uint8_t hdr[10][9], pl[10][2], sec[10], tag[10][16];
    int i;
    pair(0);
    /* long loss on RC: more than 256 frames */
    for (i = 0; i < 300; i++) {
        uint8_t h[9] = {0xFD, 2, 0, 0, 255, 190, 0xF0, 0xD2, 0}, p[2] = {7, 7}, s, t[16];
        CHECK(szlink_sec_seal(&gcs, h, p, 2, SZLINK_SEC_ENCRYPTED, 0, 0, &s, t) == 8);
        CHECK(h[3] == (uint8_t)i);
        if (i < 2 || i > 290) {
            CHECK(szlink_sec_open(&veh, h, p, 2, s, t, 8, 0) == 0);
        }
    }
    /* reordering inside the window is fine, duplicates are not */
    for (i = 0; i < 10; i++) {
        uint8_t h[9] = {0xFD, 2, 2, 0, 1, 1, 0, 0, 0};
        memcpy(hdr[i], h, 9);
        pl[i][0] = (uint8_t)i;
        pl[i][1] = 1;
        CHECK(szlink_sec_seal(&veh, hdr[i], pl[i], 2, SZLINK_SEC_SIGNED, 0, 0, &sec[i], tag[i]) == 16);
    }
    {
        const int order[10] = {1, 0, 3, 2, 9, 4, 8, 5, 7, 6};
        for (i = 0; i < 10; i++) {
            int k = order[i];
            CHECK(szlink_sec_open(&gcs, hdr[k], pl[k], 2, sec[k], tag[k], 16, 0) == 0);
        }
        for (i = 0; i < 10; i++) {
            int k = order[i];
            CHECK(szlink_sec_open(&gcs, hdr[k], pl[k], 2, sec[k], tag[k], 16, 0) != 0);
        }
    }
}

static void test_ratchet_and_epochs(void)
{
    uint8_t hdr[9] = {0xFD, 4, 1, 0, 1, 1, 0, 0, 0}, pl[4] = {1, 2, 3, 4}, sec, tag[16];
    uint32_t e;
    pair(0);
    for (e = 0; e < 12; e++) {
        /* the sender ratchets every epoch; the receiver only hears every third */
        uint32_t t = e * SZLINK_SEC_EPOCH_MS + 100;
        uint8_t h[9] = {0xFD, 4, 1, 0, 1, 1, 0, 0, 0}, p[4] = {1, 2, 3, 4}, s, tg[16];
        CHECK(szlink_sec_seal(&gcs, h, p, 4, SZLINK_SEC_ENCRYPTED, 0, t, &s, tg) == 16);
        CHECK(gcs.cur.tx_epoch == e);
        CHECK(((s & SZLINK_SEC_EPOCH_MASK) >> SZLINK_SEC_EPOCH_SHIFT) == (e & 3u));
        if (e % 3 == 0) {
            CHECK(szlink_sec_open(&veh, h, p, 4, s, tg, 16, t) == 0);
            CHECK(veh.cur.rx_cur.epoch == e);
        }
    }
    /* skew across a boundary in both directions */
    pair(0);
    CHECK(send(&gcs, &veh, SZLINK_SEC_EPOCH_MS - 1, SZLINK_SEC_EPOCH_MS + 50, SZLINK_SEC_ENCRYPTED) == 0);
    CHECK(send(&gcs, &veh, 2 * SZLINK_SEC_EPOCH_MS + 5, 2 * SZLINK_SEC_EPOCH_MS - 50, SZLINK_SEC_ENCRYPTED) == 0);
    /* late frame of the previous epoch accepted, two epochs old rejected */
    CHECK(szlink_sec_seal(&gcs, hdr, pl, 4, SZLINK_SEC_ENCRYPTED, 0, 2 * SZLINK_SEC_EPOCH_MS + 10, &sec, tag) == 16);
    CHECK(send(&gcs, &veh, 3 * SZLINK_SEC_EPOCH_MS + 10, 3 * SZLINK_SEC_EPOCH_MS + 10, SZLINK_SEC_ENCRYPTED) == 0);
    CHECK(szlink_sec_open(&veh, hdr, pl, 4, sec, tag, 16, 3 * SZLINK_SEC_EPOCH_MS + 20) == 0);
    CHECK(szlink_sec_seal(&gcs, hdr, pl, 4, SZLINK_SEC_ENCRYPTED, 0, 3 * SZLINK_SEC_EPOCH_MS + 30, &sec, tag) == 16);
    CHECK(send(&gcs, &veh, 5 * SZLINK_SEC_EPOCH_MS, 5 * SZLINK_SEC_EPOCH_MS, SZLINK_SEC_ENCRYPTED) == 0);
    CHECK(szlink_sec_open(&veh, hdr, pl, 4, sec, tag, 16, 5 * SZLINK_SEC_EPOCH_MS) != 0);
    /* session expiry */
    CHECK(szlink_sec_has_session(&veh, SZLINK_SEC_SESSION_MAX_MS - 1));
    CHECK(!szlink_sec_has_session(&veh, SZLINK_SEC_SESSION_MAX_MS));
}

static void test_rekey(void)
{
    uint8_t kex_init[SZLINK_SEC_KEX_INIT_LEN], resp[SZLINK_SEC_KEX_RESP_LEN];
    uint8_t old_init[SZLINK_SEC_KEX_INIT_LEN];
    uint8_t hdr[9] = {0xFD, 4, 1, 0, 1, 1, 0, 0, 0}, pl[4] = {1, 2, 3, 4}, sec, tag[16];
    const uint32_t t = SZLINK_SEC_REKEY_MS;
    pair(0);
    CHECK(!szlink_sec_needs_kex(&gcs, 1000));
    CHECK(send(&veh, &gcs, 4000, 4000, SZLINK_SEC_SIGNED) == 0);
    CHECK(!szlink_sec_needs_kex(&gcs, 8999));
    CHECK(szlink_sec_needs_kex(&gcs, 9000)); /* vehicle went quiet */
    CHECK(szlink_sec_needs_kex(&gcs, t));
    CHECK(szlink_sec_kex_init(&gcs, tv_gcs_eph, 1, t, old_init) == 0); /* lower timestamp */
    CHECK(szlink_sec_handle_kex_init(&veh, old_init, tv_veh_eph, t, resp) == SZLINK_SEC_ERR_REPLAY);
    CHECK(szlink_sec_kex_init(&gcs, tv_gcs_eph, 999999, t, kex_init) == 0);
    CHECK(szlink_sec_handle_kex_init(&veh, kex_init, tv_veh_eph, t, resp) == 0);
    CHECK(szlink_sec_handle_kex_init(&veh, kex_init, tv_veh_eph, t, resp) == SZLINK_SEC_ERR_REPLAY);
    CHECK(veh.pending.valid);
    /* vehicle still sends on the old session until the GCS proves the new one */
    CHECK(szlink_sec_seal(&veh, hdr, pl, 4, SZLINK_SEC_ENCRYPTED, 0, t, &sec, tag) == 16);
    CHECK(szlink_sec_handle_kex_resp(&gcs, resp, t + 20) == 0);
    CHECK(szlink_sec_open(&gcs, hdr, pl, 4, sec, tag, 16, t + 30) == 0); /* old, in grace */
    CHECK(send(&gcs, &veh, t + 40, t + 40, SZLINK_SEC_ENCRYPTED) == 0);
    CHECK(!veh.pending.valid && veh.prev.valid);
    CHECK(send(&veh, &gcs, t + 50, t + 50, SZLINK_SEC_ENCRYPTED) == 0);
    CHECK(gcs.stats.rekeys == 2 && veh.stats.rekeys == 2);
}

static void test_fec_frames(void)
{
    szlink_message_t tx, rx;
    szlink_sz_video_pkt_t pkt;
    szlink_frame_parser_t p;
    uint8_t frame[SZLINK_FRAME_MAX_LEN], env[SZLINK_FRAME_FEC_MAX_LEN], lcid, sec;
    uint16_t n, i;
    int got = 0;

    pair(0);
    memset(&pkt, 0, sizeof(pkt));
    pkt.len = 248;
    for (i = 0; i < 248; i++) {
        pkt.data[i] = (uint8_t)(i + 1);
    }
    szlink_msg_sz_video_pkt_encode(1, 1, &tx, &pkt);
    n = szlink_frame_serialize_secure(frame, &tx, SZ_LCID_VIDEO, SZLINK_SEC_ENCRYPTED,
                                      SZLINK_SEC_FEC, &veh, 0);
    CHECK(n == SZLINK_FRAME_OVERHEAD + 255 + 16);
    n = szlink_frame_fec_encode(env, frame, n, 16);
    CHECK(n == SZLINK_ECC_HEADER_LEN + 283 + 2 * 16);
    /* 8 byte errors per block are corrected (header: 2) */
    env[1] ^= 0x55;
    for (i = 0; i < 8; i++) {
        env[10 + i * 20] ^= (uint8_t)(i + 1);
        env[270 + i * 4] ^= 0xFF; /* second block starts at 262 */
    }
    szlink_frame_parser_init(&p);
    p.sec = &gcs;
    p.fec_nsym = 16;
    for (i = 0; i < n; i++) {
        got += szlink_frame_parse_char(&p, env[i], &rx, &lcid, &sec);
    }
    CHECK(got == 1 && p.authenticated && p.via_fec && p.fec_corrected == 17);
    CHECK(rx.len == 255 && (uint8_t)_MAV_PAYLOAD(&rx)[7] == 1 &&
          (uint8_t)_MAV_PAYLOAD(&rx)[254] == 248);

    /* an FEC-flagged frame sent bare is refused, as is an envelope when FEC is off */
    szlink_msg_heartbeat_pack(1, 1, &tx, 1, 2, 0, 0, 3);
    n = szlink_frame_serialize(frame, &tx, SZ_LCID_TELEMETRY, SZLINK_SEC_FEC);
    got = 0;
    for (i = 0; i < n; i++) {
        got += szlink_frame_parse_char(&p, frame[i], &rx, &lcid, &sec);
    }
    CHECK(got == 0 && p.len_errors == 1);
    n = szlink_frame_fec_encode(env, frame, n, 16);
    szlink_frame_parser_init(&p);
    for (i = 0; i < n; i++) {
        got += szlink_frame_parse_char(&p, env[i], &rx, &lcid, &sec);
    }
    CHECK(got == 0);
    /* protected frame without a security context is dropped */
    n = szlink_frame_serialize_secure(frame, &tx, SZ_LCID_TELEMETRY, SZLINK_SEC_SIGNED, 0, &gcs, 0);
    for (i = 0; i < n; i++) {
        got += szlink_frame_parse_char(&p, frame[i], &rx, &lcid, &sec);
    }
    CHECK(got == 0 && p.auth_errors == 1);
}

int main(void)
{
    test_rfc8439_aead();
    test_keys_from_secret();
    test_vectors_handshake();
    test_vectors_frames();
    test_tamper_replay_and_strangers();
    test_counter_loss_and_reorder();
    test_ratchet_and_epochs();
    test_rekey();
    test_fec_frames();
    if (failures) {
        fprintf(stderr, "%d check(s) failed\n", failures);
        return 1;
    }
    printf("szlink security tests: all passed\n");
    return 0;
}
